function searchForm(lang,q='',category='AllProducts',sort='new') {
 const t=labels(lang);
 return `<form class="catalog-search" action="${localPath('/'+category+'/',lang)}" method="get" role="search"><label class="sr-only" for="catalog-query">${t[1]}</label><input id="catalog-query" name="q" value="${escapeHtml(q)}" placeholder="${t[1]}" type="search" maxlength="100"><input type="hidden" name="sort" value="${sort}"><button>${t[2]} →</button></form>`;
}
async function upstream(path,params) {
 const u=new URL(path,DATA_ORIGIN);if(params)u.search=params.toString();
 const r=await fetch(u.href,{headers:{accept:'text/html'},redirect:'follow',signal:AbortSignal.timeout(18000)});
 if(new URL(r.url||u.href).origin!==DATA_ORIGIN)throw new Error('Unexpected catalogue destination');
 if(!r.ok){const error=new Error('Catalogue response '+r.status);error.status=r.status;throw error;}
 return r.text();
}
async function catalogueRoute(request,env) {
 const url=new URL(request.url),match=url.pathname.match(/^\/(?:(zh|de|pl|es|it|fr|pt|ro|sv)\/)?catalog(?:\/(.*))?$/);
 if(url.pathname==='/api/catalog') {
  if(request.method!=='GET')return new Response(null,{status:405});
  try{const q=new URLSearchParams();for(const k of ['q','sort','page'])if(url.searchParams.has(k))q.set(k,url.searchParams.get(k).slice(0,100));
   const result=parseList(await upstream('/AllProducts/',q));return Response.json(result,{headers:{'cache-control':'public, max-age=60'}});
  }catch{return Response.json({error:'Catalogue unavailable'},{status:502});}
 }
 if(!match)return null;
 if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405});
 const lang=match[1]||'en',tail=match[2]||'',t=labels(lang),path='/catalog/'+tail;
 if(!url.pathname.endsWith('/')&&!tail.endsWith('.html'))return Response.redirect(url.origin+url.pathname+'/'+url.search,308);
 if(tail==='AllProducts/'||tail==='AllProducts')return Response.redirect(url.origin+base(lang)+'/'+url.search,301);
 if(tail==='search.html') {
  const destination=new URL(base(lang)+'/',url.origin);destination.search=url.search;
  destination.searchParams.set('q',destination.searchParams.get('keywords')||destination.searchParams.get('q')||'');
  destination.searchParams.delete('keywords');destination.searchParams.delete('channelid');
  return Response.redirect(destination.href,302);
 }
 if(tail==='image-search/') {
  return shell(lang,path,`Joyagoo ${t[6]}`,t[16],`<p class="catalog-eyebrow">JOYAGOO SPREADSHEET</p><h1>${t[6]}</h1><p>${t[16]}</p><section class="image-search-panel"><label for="image-file" class="image-drop">${t[6]}<input id="image-file" type="file" accept="image/jpeg,image/png,image/webp"></label><img id="image-preview" alt="" hidden><p id="image-status" role="status" aria-live="polite"></p><p class="catalog-note">${t[19]}</p></section><div class="catalog-grid" id="image-results"></div>`,{noindex:true});
 }
 try {
  if(CATEGORIES.includes(tail.split('/')[0])&&/^[a-z0-9-]+\/\d+\.html$/i.test(tail)) {
   const product=parseDetail(await upstream('/'+tail));if(!product.title)return shell(lang,path,'Product unavailable','',`<h1>${t[13]}</h1>`,{status:404,noindex:true});
   const buy=buyUrl(product.sourceId);
   const schema=JSON.stringify({'@context':'https://schema.org','@type':'Product',name:product.title,sku:product.sourceId,image:product.images,...(product.price?{offers:{'@type':'Offer',price:product.price,priceCurrency:'USD',url:'https://joyagoochina.org'+prefix(lang)+path}}:{})}).replace(/</g,'\\u003c');
   return shell(lang,path,product.title,`${product.title}. ${t[8]}. ${t[15]}`,`<script type="application/ld+json">${schema}</script><a class="back" href="${base(lang)}/">← ${t[7]}</a><section class="catalog-detail"><div class="catalog-gallery"><div class="gallery-main"><button type="button" data-gallery-prev aria-label="${t[11]}">‹</button><img id="gallery-main" src="${escapeHtml(product.images[0]||'/catalog-placeholder.svg')}" alt="${escapeHtml(product.title)}" width="800" height="800"><button type="button" data-gallery-next aria-label="${t[12]}">›</button></div><div class="gallery-thumbs">${product.images.map((im,i)=>`<button type="button" data-gallery-index="${i}" aria-label="${t[8]} ${i+1}" aria-current="${i===0}"><img src="${escapeHtml(im)}" alt="${escapeHtml(product.title)} ${i+1}" width="120" height="120" loading="lazy"></button>`).join('')}</div></div><div class="catalog-product-info"><p class="catalog-eyebrow">JOYAGOO SPREADSHEET</p><h1>${escapeHtml(product.title)}</h1><p>${t[14]}: <strong>${escapeHtml(product.sourceId)}</strong></p><p class="detail-price">${money(product.price)} <small>USD</small></p>${buy?`<a class="buy-button" href="${escapeHtml(buy)}" target="_blank" rel="noopener noreferrer" data-track-event="joyagoo_product_click">${t[9]} ↗</a>`:''}<h2>${t[8]}</h2><p>${t[15]}</p></div></section><h2>${t[17]}</h2><div class="catalog-grid">${product.related.slice(0,8).map(p=>card(p,lang)).join('')}</div>`);
  }
  const cat=tail.replace(/\/$/,'')||'AllProducts';if(!CATEGORIES.includes(cat))return shell(lang,path,'Not found','',`<h1>404</h1>`,{status:404,noindex:true});
  const q=(url.searchParams.get('q')||url.searchParams.get('keywords')||'').trim().slice(0,100);
  const sort=['new','click','price'].includes(url.searchParams.get('sort'))?url.searchParams.get('sort'):'new';
  const page=Math.min(10000,Math.max(1,Number.parseInt(url.searchParams.get('page')||'1')||1));
  const params=new URLSearchParams({q,sort,page:String(page)}),data=parseList(await upstream('/'+cat+'/',params));
  const route=localPath('/'+cat+'/',lang),link=(s,p=1)=>`${route}?${new URLSearchParams({q,sort:s,page:String(p)})}`;
  const names=CATEGORY_LABELS[lang]||CATEGORY_LABELS.en,categoryTitle=names[CATEGORIES.indexOf(cat)];
  const title=cat==='AllProducts'?t[0]:`Joyagoo ${categoryTitle} Spreadsheet`;
  return shell(lang,path,title,`${title}. ${t[15]}`,`<p class="catalog-eyebrow">JOYAGOO SPREADSHEET · USD</p><h1>${title}</h1><div class="catalog-tools">${searchForm(lang,q,cat,sort)}<a class="image-search-link" href="${base(lang)}/image-search/">▧ ${t[6]}</a></div><nav class="category-filters">${CATEGORIES.map((c,i)=>`<a href="${localPath('/'+c+'/',lang)}" ${c===cat?'aria-current="page"':''}>${names[i]}</a>`).join('')}</nav><div class="sort-row">${[['new',t[3]],['click',t[4]],['price',t[5]]].map(([s,n])=>`<a href="${link(s)}" ${sort===s?'aria-current="page"':''}>${n}</a>`).join('')}<span>${page} / ${Math.max(page,data.pages)}</span></div><div class="catalog-grid">${data.products.length?data.products.map(p=>card(p,lang)).join(''):`<p class="empty-state">${t[13]}</p>`}</div><nav class="catalog-pagination">${page>1?`<a href="${link(sort,page-1)}">← ${t[11]}</a>`:''}${page<data.pages?`<a href="${link(sort,page+1)}">${t[12]} →</a>`:''}</nav>`,{noindex:!!q||sort!=='new'||page>1,query:url.search});
 } catch(error) { if(error.status===404)return shell(lang,path,t[13],t[13],`<h1>${t[13]}</h1>`,{status:404,noindex:true}); return shell(lang,path,t[20],t[20],`<h1>${t[20]}</h1><a href="${base(lang)}/">${t[7]}</a>`,{status:503,noindex:true}); }
}

function renderHome(lang,products,{snapshot=false}={}) {
 const h=EXTRA[lang],t=COPY[lang],pre=lang==='en'?'':'/'+lang,items=products.slice(0,4),editorial=EDITORIAL[lang],cats=CATEGORY_LABELS[lang];
 const json=JSON.stringify({'@context':'https://schema.org','@type':'WebSite',name:'Joyagoo Spreadsheet',url:'https://joyagoochina.org'+pre+'/',inLanguage:lang,description:h.intro,potentialAction:{'@type':'SearchAction',target:'https://joyagoochina.org'+pre+'/catalog/?q={search_term_string}','query-input':'required name=search_term_string'}}).replace(/</g,'\\u003c');
 const faq=editorial.faq;
 const faqJson=JSON.stringify({'@context':'https://schema.org','@type':'FAQPage',inLanguage:lang,mainEntity:faq.items.map(item=>({'@type':'Question',name:item.q,acceptedAnswer:{'@type':'Answer',text:item.a}}))}).replace(/</g,'\\u003c');
 const body=`<script type="application/ld+json">${json}</script><section class="discovery-hero"><div class="discovery-copy"><p class="catalog-eyebrow">JOYAGOO SPREADSHEET · FINDS & QC</p><h1>${h.title}</h1><p class="hero-description">${h.intro}</p>${searchForm(lang)}<div class="hero-actions"><a class="image-search-link" href="${pre}/catalog/image-search/">▧ ${t[6]}</a><a class="text-cta" href="${pre}/catalog/">${t[7]} →</a></div><p class="independent-label">${h.independent}</p></div><div class="hero-finds" aria-label="${h.latest}">${items.map((p,i)=>`<a class="hero-find" href="${pre}/catalog${p.path}"><img src="${escapeHtml(p.image)}" width="360" height="360" alt="${escapeHtml(p.title)}" ${i<2?'fetchpriority="high"':'loading="lazy"'}><span>${escapeHtml(p.title)}</span><strong>$${Number(p.price).toFixed(2)} <small>USD</small></strong></a>`).join('')}</div></section>${snapshot?`<p class="catalog-note">${h.snapshot}: ${SNAPSHOT.date} · ${t[15]}</p>`:''}<section class="home-categories" aria-labelledby="category-heading"><h2 id="category-heading">${h.categories}</h2><nav>${[1,2,3,4,7,11].map(i=>`<a href="${pre}/catalog/${CATEGORIES[i]}/"><span>${cats[i]}</span><b>↗</b></a>`).join('')}</nav></section><section class="home-steps"><h2>${h.how}</h2><div>${[['01',h.find,h.findBody],['02',h.check,h.checkBody],['03',h.buy,h.buyBody]].map(([n,title,text])=>`<article><span>${n}</span><h3>${title}</h3><p>${text}</p></article>`).join('')}</div></section><section class="home-library"><div class="home-section-title"><h2>${h.guides}</h2><a href="${pre}/articles/">${h.allArticles} →</a></div><nav class="home-guide-links">${editorial.guides.map(g=>`<a href="${pre}/${g.slug}/">${escapeHtml(g.title)} ↗</a>`).join('')}</nav><div class="home-articles">${editorial.articles.map(a=>`<a href="${pre}/${a.slug}/"><img src="${escapeHtml(a.image.src)}" alt="${escapeHtml(a.title)}" width="400" height="400" loading="lazy"><h3>${escapeHtml(a.title)}</h3></a>`).join('')}</div></section><section id="faq" class="home-faq" aria-labelledby="home-faq-heading"><script type="application/ld+json">${faqJson}</script><div class="home-section-title"><h2 id="home-faq-heading">${escapeHtml(faq.title)}</h2><a href="${pre}/faq/">${escapeHtml(faq.label)} →</a></div><p class="home-faq-intro">${escapeHtml(faq.intro)}</p><div class="home-faq-list">${faq.items.map(item=>`<details><summary>${escapeHtml(item.q)}</summary><p>${escapeHtml(item.a)}</p></details>`).join('')}</div></section><section class="home-context"><div><h2>${h.aboutTitle}</h2><p>${h.aboutBody}</p></div><div><h2>${h.budgetTitle}</h2><p>${h.budgetBody}</p></div></section>`;
 const response=shell(lang,'/',h.title,h.intro,body);if(snapshot){response.headers.set('x-catalog-snapshot',SNAPSHOT.date);response.headers.set('cache-control','public, max-age=0, s-maxage=30');}return response;
}
async function homepageRoute(request) {
 const path=new URL(request.url).pathname,lang=path==='/'?'en':path.match(/^\/(zh|de|pl|es|it|fr|pt|ro|sv)\/$/)?.[1];
 if(!lang)return null;
 try {const {products}=parseList(await upstream('/AllProducts/',new URLSearchParams({sort:'new'})));if(!products.length)throw Error('Empty upstream catalogue');return renderHome(lang,products);}catch {return renderHome(lang,SNAPSHOT.products,{snapshot:true});}
}

const RELEASE='2026-10-13-joyagoo-mobile-inner-v2';
const SITEMAP_INDEX='<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><sitemap><loc>https://joyagoochina.org/editorial-sitemap.xml</loc></sitemap><sitemap><loc>https://joyagoochina.org/catalog-sitemap.xml</loc></sitemap></sitemapindex>';
async function commerceRoutes(request,env,ctx) {
 const url=new URL(request.url),locale=url.pathname.match(/^\/(zh|de|pl|es|it|fr|pt|ro|sv)(?=\/|$)/)?.[0]||'',bare=url.pathname.slice(locale.length)||'/';
 if(locale&&url.pathname===locale)return Response.redirect(url.origin+locale+'/'+url.search,301);
 if(bare==='/sitemap.xml')return new Response(SITEMAP_INDEX,{headers:{'content-type':'application/xml; charset=utf-8','cache-control':'public, max-age=300'}});
 if(url.pathname==='/catalog-sitemap.xml'){
  try {
   const xml=await upstream('/sitemap.xml');
   const paths=[...new Set([...xml.matchAll(/<loc>https:\/\/(?:www\.)?cnbuycha\.com([^<]+)<\/loc>/g)].map(m=>m[1]).filter(p=>/^\/[a-z0-9-]+\/\d+\.html$/i.test(p)||CATEGORIES.some(c=>p==='/'+c+'/')))];
   const entries=LANGS.flatMap(l=>['/catalog/',...paths.filter(p=>p!='/AllProducts/').map(p=>'/catalog'+p)].map(p=>`<url><loc>https://joyagoochina.org${l==='en'?'':'/'+l}${p}</loc></url>`));
   if(entries.length>50000)throw Error('Catalogue sitemap needs splitting');
   return new Response('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+entries.join('')+'</urlset>',{headers:{'content-type':'application/xml; charset=utf-8','cache-control':'public, max-age=600'}});
  }catch{return new Response('Sitemap temporarily unavailable',{status:503,headers:{'cache-control':'no-store'}});}
 }
 const normal=bare.endsWith('/')?bare:bare+'/';
 const oldProduct=LEGACY_PRODUCTS[normal];
 if(oldProduct)return Response.redirect(url.origin+locale+'/catalog'+oldProduct,301);
 if(['/spreadsheet/','/categories/','/finds/','/products/','/search.html/'].includes(normal)){
  const dest=new URL(locale+'/catalog/',url.origin);dest.search=url.search;
  if(dest.searchParams.has('keywords')){dest.searchParams.set('q',dest.searchParams.get('keywords'));dest.searchParams.delete('keywords');}
  dest.searchParams.delete('channelid');return Response.redirect(dest.href,301);
 }
 if(!['GET','HEAD'].includes(request.method))return catalogueRoute(request,env);
 const isHome=bare==='/',isCatalog=bare.startsWith('/catalog')||url.pathname==='/api/catalog';
 if(!isHome&&!isCatalog)return null;
 const edge=globalThis.caches?.default,keyURL=new URL(url);keyURL.searchParams.set('__commerce_version',RELEASE);
 const key=new Request(keyURL,{method:'GET'});
 if(edge&&request.method==='GET'){const cached=await edge.match(key);if(cached)return cached;}
 const response=isHome?await homepageRoute(request):await catalogueRoute(request,env);
 if(!response)return null;
 response.headers.set('x-joyagoo-release',RELEASE);
 if(edge&&ctx?.waitUntil&&request.method==='GET'&&response.status===200&&!response.headers.has('x-catalog-snapshot'))ctx.waitUntil(edge.put(key,response.clone()));
 return request.method==='HEAD'?new Response(null,{status:response.status,headers:response.headers}):response;
}

const primaryHost = "joyagoochina.org";
const staticLocaleCodes = new Set([
  "en",
  "zh",
  "de",
  "pl",
  "es",
  "it",
  "fr",
  "pt",
  "ro",
  "sv",
]);
const browserHtmlCacheControl = "public, max-age=0";
const edgeHtmlCacheControl =
  "public, max-age=21600, stale-while-revalidate=86400";
const htmlCacheVersion = "2026-10-13-joyagoo-mobile-inner-v2";
const mobileInnerStyle = '<link rel="stylesheet" href="/mobile-inner.css?v=20261013-inner-v2">';
const outboundEndpoint = "/api/outbound-click";
const maxOutboundPayloadBytes = 4096;

const jsonResponse = (message, status) =>
  new Response(JSON.stringify({ error: message }), {
    status,
    headers: {
      "cache-control": "no-store",
      "content-type": "application/json; charset=utf-8",
    },
  });

const cleanText = (value, maxLength) => {
  if (typeof value !== "string") return undefined;
  const cleaned = value.trim().slice(0, maxLength);
  return cleaned || undefined;
};

async function handleOutboundClick(request, requestUrl) {
  if (request.method !== "POST") {
    return new Response(null, {
      status: 405,
      headers: { allow: "POST", "cache-control": "no-store" },
    });
  }

  const origin = request.headers.get("origin");
  if (origin) {
    try {
      if (new URL(origin).origin !== requestUrl.origin) {
        return jsonResponse("Cross-origin analytics requests are not accepted.", 403);
      }
    } catch {
      return jsonResponse("Invalid request origin.", 403);
    }
  }

  const declaredLength = Number(request.headers.get("content-length") ?? 0);
  if (declaredLength > maxOutboundPayloadBytes) {
    return jsonResponse("Analytics payload is too large.", 413);
  }

  const rawBody = await request.text();
  if (new TextEncoder().encode(rawBody).byteLength > maxOutboundPayloadBytes) {
    return jsonResponse("Analytics payload is too large.", 413);
  }

  let body;
  try {
    body = JSON.parse(rawBody);
  } catch {
    return jsonResponse("Invalid analytics payload.", 400);
  }
  if (!body || typeof body !== "object" || Array.isArray(body)) {
    return jsonResponse("Invalid analytics payload.", 400);
  }

  const rawDestination = cleanText(body.destination, 500);
  if (!rawDestination) return jsonResponse("Missing destination.", 400);

  let destination;
  try {
    destination = new URL(rawDestination);
  } catch {
    return jsonResponse("Invalid destination.", 400);
  }
  if (!new Set(["joyagoo.com"]).has(destination.hostname)) {
    return jsonResponse("Destination is not the linked product store.", 400);
  }

  const sourcePage = cleanText(body.source_page, 300);
  const language = cleanText(body.language, 12);
  const productId = cleanText(body.product_id, 32);
  const category = cleanText(body.category, 80);
  const linkKind = cleanText(body.link_kind, 40) ?? "link";

  console.log(
    JSON.stringify({
      type: "joyagoo_outbound_click",
      destination: `${destination.origin}${destination.pathname}`,
      source_page: sourcePage?.startsWith("/") ? sourcePage : "/",
      language: language && staticLocaleCodes.has(language) ? language : "en",
      link_kind: linkKind,
      ...(productId ? { product_id: productId } : {}),
      ...(category ? { category } : {}),
    }),
  );

  return new Response(null, {
    status: 204,
    headers: { "cache-control": "no-store" },
  });
}

const isCacheableHtmlRequest = (request, url) =>
  request.method === "GET" &&
  url.hostname === primaryHost &&
  (url.pathname === "/" || url.pathname.endsWith("/")) &&
  !url.pathname.startsWith("/api/") &&
  !request.headers.has("authorization") &&
  !request.headers.has("range");

const htmlCacheKey = (url) => {
  const normalized = new URL(url.origin);
  normalized.pathname = url.pathname;
  normalized.searchParams.set("__html_cache_version", htmlCacheVersion);
  return new Request(normalized.toString(), {
    method: "GET",
    headers: { accept: "text/html" },
  });
};

const htmlCache = () => globalThis.caches?.default;
const notFoundHtml = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="robots" content="noindex,follow">
    <title>Page Not Found | Joyagoo China</title>
    <style>
      :root{font-family:Arial,sans-serif;color:#06101f;background:#f5efe5}
      *{box-sizing:border-box}body{min-height:100vh;margin:0;display:grid;place-items:center;padding:2rem}
      main{width:min(760px,100%);text-align:center}small{color:#d64a17;font-weight:800;letter-spacing:.13em}
      h1{margin:1rem 0;font-family:Georgia,serif;font-size:clamp(3rem,10vw,7rem);line-height:.92;letter-spacing:-.06em}
      p{color:#59616d;line-height:1.7}nav{display:flex;flex-wrap:wrap;justify-content:center;gap:.7rem;margin-top:2rem}
      a{padding:.85rem 1rem;border:1px solid #06101f;border-radius:7px;color:#06101f;font-size:.78rem;font-weight:800;text-decoration:none;text-transform:uppercase}
      a:first-child{background:#06101f;color:#fff}
    </style>
  </head>
  <body>
    <main>
      <small>404 · PAGE NOT FOUND</small>
      <h1>This page does not exist.</h1>
      <p>The address may be mistyped or the page may have moved. Continue with a real product, guide, article or answer.</p>
      <nav aria-label="Helpful destinations">
        <a href="/">Home</a><a href="/spreadsheet/">Products</a><a href="/articles/">Articles</a><a href="/faq/">FAQ</a>
      </nav>
    </main>
  </body>
</html>`;

const worker = {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.hostname === `www.${primaryHost}`) {
      url.hostname = primaryHost;
      return Response.redirect(url.toString(), 301);
    }

    if (url.pathname === "/sitemap-main.xml") {
      return Response.redirect(`https://${primaryHost}/sitemap.xml`, 301);
    }

    if (url.pathname === outboundEndpoint) {
      return handleOutboundClick(request, url);
    }

    const commerce = await commerceRoutes(request, env, ctx);
    if (commerce) return commerce;

    const cacheableHtml = isCacheableHtmlRequest(request, url);
    const cacheKey = cacheableHtml ? htmlCacheKey(url) : undefined;
    const edgeCache = cacheKey ? htmlCache() : undefined;
    if (cacheKey && edgeCache) {
      try {
        const cached = await edgeCache.match(cacheKey);
        if (cached) return cached;
      } catch (error) {
        console.error(
          JSON.stringify({
            type: "joyagoo_html_cache_match_error",
            path: url.pathname,
            message: error instanceof Error ? error.message : String(error),
          }),
        );
      }
    }

    let response = await env.ASSETS.fetch(request);
    if (response.status === 404 && request.method === "GET") {
      response = new Response(notFoundHtml, {
        status: 404,
        statusText: "Not Found",
        headers: {
          "content-type": "text/html; charset=utf-8",
          "cache-control": "no-store",
        },
      });
    }

    const firstSegment = url.pathname.split("/").filter(Boolean)[0];
    const language =
      firstSegment && staticLocaleCodes.has(firstSegment) ? firstSegment : "en";
    const headers = new Headers(response.headers);
    headers.set("x-content-type-options", "nosniff");
    headers.set("referrer-policy", "strict-origin-when-cross-origin");
    if ((headers.get("content-type") ?? "").includes("text/html")) {
      headers.set("content-language", language);
      if (request.method === "GET" && response.status === 200) {
        headers.delete("content-length");
        headers.delete("content-encoding");
        headers.delete("etag");
        response = new HTMLRewriter()
          .on("head", { element(element) { element.append(mobileInnerStyle, { html: true }); } })
          .transform(response);
      }
    }

    const shouldStore =
      Boolean(cacheKey && edgeCache) &&
      response.status === 200 &&
      (headers.get("content-type") ?? "").includes("text/html") &&
      !headers.has("set-cookie");
    if (shouldStore) {
      headers.set("cache-control", browserHtmlCacheControl);
      headers.set("cloudflare-cdn-cache-control", edgeHtmlCacheControl);
      headers.set("cache-tag", "joyagoo-html");
    } else if (response.status >= 400) {
      headers.set("cache-control", "no-store");
      headers.delete("cloudflare-cdn-cache-control");
      headers.delete("cache-tag");
    }

    const finalResponse = new Response(response.body, {
      status: response.status,
      statusText: response.statusText,
      headers,
    });

    if (shouldStore && cacheKey && edgeCache && ctx?.waitUntil) {
      ctx.waitUntil(
        edgeCache.put(cacheKey, finalResponse.clone()).catch((error) => {
          console.error(
            JSON.stringify({
              type: "joyagoo_html_cache_put_error",
              path: url.pathname,
              message: error instanceof Error ? error.message : String(error),
            }),
          );
        }),
      );
    }

    return finalResponse;
  },
};

export default worker;
